371	    /**
372	     * Populate the owner's household size: the number of owners sharing this owner's
373	     * {@code householdId} (including the owner itself). An owner with no household is a household
374	     * of one.
375	     *
376	     * @param owner the owner whose household size should be computed and set
377	     */
378	    private void populateHouseholdSize(Owner owner) {
379	        String householdId = owner.getHouseholdId();
380	        if (!StringUtils.hasText(householdId)) {
381	            owner.setHouseholdSize(1);
382	            return;
383	        }
384	        int size = (int) this.clinicService.findAllOwners().stream()
385	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
386	            .count();
387	        owner.setHouseholdSize(size);
388	    }
389	
390	    /**
391	     * Generate a customer code formatted {@code <REGION>-<HASH8>}, where {@code REGION} is the region
392	     * code derived from the owner's identity (postcode range first, then the city-to-region table,
393	     * otherwise {@code UNKNOWN}) and {@code HASH8} is the first eight upper-case hex characters of the
394	     * SHA-256 digest of {@code normalizedTelephone + lastName} (e.g. {@code NSW-1A2B3C4D}). There is no
395	     * longer any per-city sequence number.
396	     *
397	     * @param owner the owner whose (already-normalized) telephone, last name, postcode and city are read
398	     * @return the generated (collision-free) customer code
399	     */
400	    private String generateCustomerCode(Owner owner) {
401	        String region = deriveRegion(owner.getPostcode(), owner.getCity());
402	        String hash8 = shortSha256Hex(owner.getTelephone() + owner.getLastName(), 8);
403	        String baseCode = region + "-" + hash8;
404	        return deduplicateCustomerCode(baseCode);
405	    }
406	
407	    /**
408	     * Return a customer code that does not collide with any existing owner's customer code. When the
409	     * given base code is already unique it is returned unchanged; otherwise {@code -<n>} is appended
410	     * with the smallest {@code n} of 2 or more that makes the result unique (e.g. {@code NSW-1A2B3C4D},
411	     * then {@code NSW-1A2B3C4D-2}, {@code NSW-1A2B3C4D-3}, ...). The incoming owner is not yet
412	     * persisted, so it never counts as a collision with itself.
413	     *
414	     * @param baseCode the computed {@code <REGION>-<HASH8>} customer code
415	     * @return the de-duplicated customer code
416	     */
417	    private String deduplicateCustomerCode(String baseCode) {
418	        java.util.Set<String> existingCodes = this.clinicService.findAllOwners().stream()
419	            .map(Owner::getCustomerCode)
420	            .filter(java.util.Objects::nonNull)
421	            .collect(java.util.stream.Collectors.toSet());
422	        if (!existingCodes.contains(baseCode)) {
423	            return baseCode;
424	        }
425	        int n = 2;
426	        String candidate = baseCode + "-" + n;
427	        while (existingCodes.contains(candidate)) {
428	            n++;
429	            candidate = baseCode + "-" + n;
430	        }
431	        return candidate;
432	    }
433	
434	    /**
435	     * Derive the region code for an owner's identity. The postcode is preferred: when present and it
436	     * falls within a known region's inclusive 4-digit range (NSW 2000-2099, VIC 3000-3099,
437	     * QLD 4000-4099) that region is returned. Otherwise fall back to the pinned city-to-region table
438	     * (Sydney->NSW, Melbourne->VIC, Brisbane->QLD), and finally {@code UNKNOWN} for a city with no
439	     * known region.
440	     *
441	     * @param postcode the owner's postcode, may be {@code null}
442	     * @param city     the owner's city
443	     * @return the derived region code
444	     */
445	    private String deriveRegion(String postcode, String city) {
446	        if (postcode != null && POSTCODE_PATTERN.matcher(postcode).matches()) {
447	            int value = Integer.parseInt(postcode);
448	            for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGE.entrySet()) {
449	                int[] range = entry.getValue();
450	                if (value >= range[0] && value <= range[1]) {
451	                    return entry.getKey();
452	                }
453	            }
454	        }
455	        String region = CITY_REGION.get(city);
456	        return region != null ? region : "UNKNOWN";
457	    }
458	
459	    /**
460	     * Return the first {@code length} upper-case hex characters of the SHA-256 digest of the UTF-8
461	     * bytes of {@code input}.
462	     *
463	     * @param input  the value to digest
464	     * @param length the number of leading hex characters to return
465	     * @return the truncated upper-case hex digest
466	     */
467	    private String shortSha256Hex(String input, int length) {
468	        try {
469	            byte[] digest = MessageDigest.getInstance("SHA-256")
470	                .digest(input.getBytes(StandardCharsets.UTF_8));
471	            StringBuilder sb = new StringBuilder(digest.length * 2);
472	            for (byte b : digest) {
473	                sb.append(String.format("%02x", b));
474	            }
475	            return sb.substring(0, length).toUpperCase(Locale.ROOT);
476	        } catch (java.security.NoSuchAlgorithmException e) {
477	            throw new IllegalStateException("SHA-256 not available", e);
478	        }
479	    }
