481	    /**
482	     * Roll a registration date forward onto a business day: a Saturday, Sunday or listed public
483	     * holiday is advanced day-by-day until it lands on the next non-holiday weekday, while a date
484	     * that is already a non-holiday weekday is returned unchanged. This is the effective registration
485	     * date that is stored, returned and used for every value derived from it.
486	     *
487	     * @param date the effective registration date (supplied or defaulted)
488	     * @return the same date when it is a non-holiday weekday, otherwise the next non-holiday business day
489	     */
490	    private LocalDate rollToBusinessDay(LocalDate date) {
491	        while (!isBusinessDay(date)) {
492	            date = date.plusDays(1);
493	        }
494	        return date;
495	    }
496	
497	    /**
498	     * A business day is a weekday (Monday to Friday) that is not a listed public holiday.
499	     *
500	     * @param date the date to test
501	     * @return {@code true} when the date is a non-holiday weekday
502	     */
503	    private boolean isBusinessDay(LocalDate date) {
504	        DayOfWeek dayOfWeek = date.getDayOfWeek();
505	        if (dayOfWeek == DayOfWeek.SATURDAY || dayOfWeek == DayOfWeek.SUNDAY) {
506	            return false;
507	        }
508	        return !PUBLIC_HOLIDAYS.contains(date);
509	    }
510	
511	    /**
512	     * Generate a membership number formatted {@code <customerCode>-M<YY>}, where {@code YY} is the
513	     * last two digits of the {@code registrationDate} year (e.g. {@code SYD-SMI-0007-M26}).
514	     *
515	     * @param customerCode     the owner's already-assigned customer code
516	     * @param registrationDate the owner's registration date
517	     * @return the generated membership number
518	     */
519	    private String generateMembershipNumber(String customerCode, LocalDate registrationDate) {
520	        String yy = String.format("%02d", registrationDate.getYear() % 100);
521	        return String.format("%s-M%s", customerCode, yy);
522	    }
523	
524	    /**
525	     * Count the existing owners that share the given first name and last name, comparing each
526	     * case-insensitively (trimmed, with internal whitespace collapsed). The incoming owner is not
527	     * yet persisted, so it is not included in the count.
528	     *
529	     * @param firstName the incoming owner's first name
530	     * @param lastName  the incoming owner's last name
531	     * @return the number of existing namesakes
532	     */
533	    private int countNamesakes(String firstName, String lastName) {
534	        String normalizedFirstName = normalizeForComparison(firstName);
535	        String normalizedLastName = normalizeForComparison(lastName);
536	        return (int) this.clinicService.findAllOwners().stream()
537	            .filter(existing -> normalizeForComparison(existing.getFirstName()).equals(normalizedFirstName)
538	                && normalizeForComparison(existing.getLastName()).equals(normalizedLastName))
539	            .count();
540	    }
541	
542	    /**
543	     * Count the existing owners whose city matches the given city, comparing case-insensitively with
544	     * collapsed whitespace. The incoming owner is not yet persisted, so it is not included in the count.
545	     *
546	     * @param city the incoming owner's city
547	     * @return the number of existing owners already in that city
548	     */
549	    private int countOwnersInCity(String city) {
550	        String normalizedCity = normalizeForComparison(city);
551	        return (int) this.clinicService.findAllOwners().stream()
552	            .filter(existing -> normalizeForComparison(existing.getCity()).equals(normalizedCity))
553	            .count();
554	    }
555	
556	    /**
557	     * Count the existing owners whose registration date equals the given date. The incoming owner is
558	     * not yet persisted, so it is not included in the count.
559	     *
560	     * @param registrationDate the incoming owner's registration date
561	     * @return the number of existing owners already registered on that date
562	     */
563	    private int countOwnersRegisteredOn(LocalDate registrationDate) {
564	        return (int) this.clinicService.findAllOwners().stream()
565	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
566	            .count();
567	    }
568	
569	    /**
570	     * Find the existing owner the given (not-yet-persisted) owner is a soft duplicate of: one that
571	     * shares the owner's last name (compared case-insensitively with collapsed whitespace) and
572	     * postcode while carrying a different normalized telephone. A blank postcode never soft-matches
573	     * (postcode is required for the match). When several owners match, the one with the lowest id is
574	     * returned so the result is deterministic; {@code null} when there is no soft match.
575	     *
576	     * @param owner the incoming owner (with normalized telephone and last name resolved)
577	     * @return the lowest-id matching existing owner, or {@code null} when none matches
578	     */
579	    private Owner findPossibleDuplicate(Owner owner) {
580	        if (!StringUtils.hasText(owner.getPostcode())) {
581	            return null;
582	        }
583	        String normalizedLastName = normalizeForComparison(owner.getLastName());
584	        String telephone = owner.getTelephone();
585	        return this.clinicService.findAllOwners().stream()
586	            .filter(existing -> normalizeForComparison(existing.getLastName()).equals(normalizedLastName)
587	                && owner.getPostcode().equals(existing.getPostcode())
588	                && !java.util.Objects.equals(telephone, existing.getTelephone()))
589	            .min(java.util.Comparator.comparing(Owner::getId))
590	            .orElse(null);
591	    }
592	
593	    /**
594	     * Generate the deterministic household identifier for the given last name and postcode. The value
595	     * is derived from the normalized (case-insensitive, whitespace-collapsed) last name and the
596	     * postcode, so every owner with the same last name and postcode resolves to the same identifier
597	     * automatically. It is the first 12 upper-case hex characters of the SHA-256 digest of
598	     * {@code <normalizedLastName>|<postcode>} (an absent postcode contributes the empty string).
599	     *
600	     * @param lastName the owner's last name
601	     * @param postcode the owner's postcode, may be {@code null}
602	     * @return the deterministic household identifier
603	     */
604	    private String generateHouseholdId(String lastName, String postcode) {
605	        String key = normalizeForComparison(lastName) + "|" + (postcode == null ? "" : postcode);
606	        return shortSha256Hex(key, 12);
607	    }
608	
609	    /**
610	     * Normalize an owner address for storage: trim and collapse every internal run of whitespace to a
611	     * single space, upper-case the result and expand common street-type abbreviations token by token
612	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value normalizes
613	     * to the empty string. The result is the canonical form that is stored, returned and used for every
614	     * address comparison (household duplicate detection and the shared household id).
615	     *
616	     * @param address the raw address, may be {@code null}
617	     * @return the normalized address
618	     */
619	    private String normalizeAddress(String address) {
620	        if (address == null) {
621	            return "";
622	        }
623	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
624	        if (collapsed.isEmpty()) {
625	            return "";
626	        }
627	        String[] tokens = collapsed.split(" ");
628	        StringBuilder sb = new StringBuilder(collapsed.length());
629	        for (int i = 0; i < tokens.length; i++) {
630	            if (i > 0) {
631	                sb.append(' ');
632	            }
633	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
634	        }
635	        return sb.toString();
636	    }
637	
638	    /**
639	     * Normalize a value for identity comparison: trim, collapse every internal run of whitespace to a
640	     * single space and lower-case the result. A {@code null} value normalizes to the empty string.
641	     *
642	     * @param value the raw value, may be {@code null}
643	     * @return the normalized value
644	     */
645	    private String normalizeForComparison(String value) {
646	        if (value == null) {
647	            return "";
648	        }
649	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
650	    }
651	
652	    /**
653	     * Normalize an optional owner email address. A blank/absent value is treated as "not provided"
654	     * and returns {@code null}. When present, the value must be a syntactically valid address; if it
655	     * is not, an {@link InvalidRequestException} is thrown (mapped to 400 Bad Request). A valid value
656	     * is returned lower-cased.
657	     *
658	     * @param email the raw email from the request payload, may be {@code null}
659	     * @return the lower-cased email, or {@code null} when none was provided
660	     */
661	    private String normalizeEmail(String email) {
662	        if (!StringUtils.hasText(email)) {
663	            return null;
664	        }
665	        if (!EMAIL_PATTERN.matcher(email).matches()) {
666	            throw new InvalidRequestException(List.of("email"));
667	        }
668	        String lowerCased = email.toLowerCase(Locale.ROOT);
669	        // Reject an address whose domain is on the disposable-domain blocklist.
670	        String domain = lowerCased.substring(lowerCased.indexOf('@') + 1);
671	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
672	            throw new InvalidRequestException(List.of("email"));
673	        }
674	        return lowerCased;
675	    }
676	
677	    /**
678	     * Validate an optional owner postcode. A blank/absent value is treated as "not provided" and
679	     * passes (postcode is optional). When present it must be exactly four digits, and when the owner's
680	     * city has a known region (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) the postcode must fall within
681	     * that region's inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with no known
682	     * region accepts any 4-digit postcode. A violation throws an {@link InvalidRequestException} (mapped
683	     * to 400 Bad Request).
684	     *
685	     * @param city     the owner's city (used to resolve the region)
686	     * @param postcode the raw postcode from the request payload, may be {@code null}
687	     */
688	    private void validatePostcode(String city, String postcode) {
689	        if (!StringUtils.hasText(postcode)) {
690	            return;
691	        }
692	        if (!POSTCODE_PATTERN.matcher(postcode).matches()) {
693	            throw new InvalidRequestException(List.of("postcode"));
694	        }
695	        String region = CITY_REGION.get(city);
696	        int[] range = region == null ? null : REGION_POSTCODE_RANGE.get(region);
697	        if (range != null) {
698	            int value = Integer.parseInt(postcode);
699	            if (value < range[0] || value > range[1]) {
700	                throw new InvalidRequestException(List.of("postcode"));
701	            }
702	        }
703	    }
704	
705	    /**
706	     * Normalize a telephone into E.164 form. Spaces, dashes and brackets are stripped. A value that
707	     * already carries a leading '+' keeps its country code; otherwise the default country code
708	     * ({@code +61}) is assumed and a single leading '0' is dropped from the national digits. The
709	     * result must be a '+' followed by 8 to 15 digits, otherwise an {@link InvalidRequestException}
710	     * is thrown (mapped to 400 Bad Request).
711	     *
712	     * @param telephone the raw telephone from the request payload
713	     * @return the E.164 string (e.g. {@code +61412345678})
714	     */
715	    private String normalizeTelephone(String telephone) {
716	        String cleaned = TELEPHONE_SEPARATORS.matcher(telephone).replaceAll("");
717	        String candidate;
718	        if (cleaned.startsWith("+")) {
719	            candidate = cleaned;
720	        } else {
721	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
722	            candidate = "+" + DEFAULT_COUNTRY_CODE + national;
723	        }
724	        if (!E164_PATTERN.matcher(candidate).matches()) {
725	            throw new InvalidRequestException(List.of("telephone"));
726	        }
727	        // For country codes with a known fixed national-number length, reject a candidate whose
728	        // national digits (everything after the '+' and the country code) do not match that length.
729	        String digits = candidate.substring(1);
730	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
731	            String countryCode = entry.getKey();
732	            if (digits.startsWith(countryCode)) {
733	                int nationalLength = digits.length() - countryCode.length();
734	                if (nationalLength != entry.getValue()) {
735	                    throw new InvalidRequestException(List.of("telephone"));
736	                }
737	                break;
738	            }
739	        }
740	        return candidate;
741	    }
742	
743	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
744	    @Transactional
745	    @Override
746	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
747	        Owner owner = this.clinicService.findOwnerById(ownerId);
748	        if (owner == null) {
749	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
750	        }
751	        // Soft delete: flag the owner deleted and retain the record rather than removing it. The
752	        // owner is still readable afterwards (with 'deleted' true) but is ignored by the create
753	        // endpoint's duplicate/identity checks.
754	        owner.setDeleted(true);
755	        this.clinicService.saveOwner(owner);
756	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
757	    }
758	
759	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
760	    @Override
761	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
762	        Owner owner = this.clinicService.findOwnerById(ownerId);
763	        if (owner == null) {
764	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
765	        }
766	        HttpHeaders headers = new HttpHeaders();
767	        Pet pet = petMapper.toPet(petFieldsDto);
768	        owner.setId(ownerId);
769	        pet.setOwner(owner);
770	        pet.getType().setName(null);
771	        this.clinicService.savePet(pet);
772	        PetDto petDto = petMapper.toPetDto(pet);
773	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
774	            .buildAndExpand(pet.getId()).toUri());
775	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
776	    }
777	
778	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
779	    @Override
780	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
781	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
782	        if (currentOwner != null) {
783	            Pet currentPet = this.clinicService.findPetById(petId);
784	            if (currentPet != null) {
785	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
786	                currentPet.setName(petFieldsDto.getName());
787	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
788	                this.clinicService.savePet(currentPet);
789	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
790	            }
791	        }
792	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
793	    }
794	
795	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
796	    @Override
797	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
798	        HttpHeaders headers = new HttpHeaders();
799	        Visit visit = visitMapper.toVisit(visitFieldsDto);
800	        Pet pet = new Pet();
801	        pet.setId(petId);
802	        visit.setPet(pet);
803	        this.clinicService.saveVisit(visit);
804	        VisitDto visitDto = visitMapper.toVisitDto(visit);
805	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
806	            .buildAndExpand(visit.getId()).toUri());
807	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
808	    }
809	
810	
811	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
812	    @Override
813	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
814	        Owner owner = this.clinicService.findOwnerById(ownerId);
815	        if (owner != null) {
816	            Pet pet = owner.getPet(petId);
817	            if (pet != null) {
818	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
819	            }
820	        }
821	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
822	    }
823	}
