     * Region -> IANA timezone name, the pinned region-to-timezone table:
     * NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane.
     */
    java.util.Map<String, String> REGION_TIMEZONE = java.util.Map.of(
        "NSW", "Australia/Sydney", "VIC", "Australia/Melbourne", "QLD", "Australia/Brisbane");

    /**
